// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    address bankEoa = address(0xB0B);
    address player = address(0x1234);

    function setUp() public {
        vm.prank(bankEoa);
        c = new EtherLotto();
    }

    function testFuzz_property(uint256 ts, uint256 diff) public {
        ts = bound(ts, 1, type(uint64).max);
        diff = bound(diff, 0, type(uint32).max);
        vm.warp(ts);
        vm.roll(diff);

        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // General rule: the contract's ether balance always equals the recorded pot.
        // Reference: win pays out everything and resets pot to 0 (balance 0 == pot 0);
        // loss adds 10 to both. Mutant: win leaves pot = 1 while balance is 0.
        assertTrue(address(c).balance == c.pot());
    }
}
